-- 0182_seed_book_chapter_rows.sql
--
-- ADR-0062：`book_chapter` 默认卷章目录种子。把 `ctwh/BookChapter.sql` 445 行
-- 随迁移播种，部署到任何位置 `book_chapter` 都自带同一份目录（表结构见 0181）。
--
-- ## 数据变换（2026-11-04 审计量化，全部实测）
--
-- - id：`randomShortUUID()` 11 位，由 `.scratch/book-chapter-module/gen-0183.mjs`
--   一次性预计算（源 Id 1..449 不复用）；445 个全唯一，与 book_info 0175 种子
--   10 个 id 无碰撞。运行期不再生成。
-- - chapter_no：按源 Id 升序赋 1..445（显示/排序唯一真键，UNIQUE 索引兜底）。
--   源 ChapterSection 跨书异构（0..26 / 4001001.. / 904000203 混杂），
--   **不作排序键**，仅存进 chapter_section 供追溯。
-- - chapter_header：**全格式保真、不 trim 不 strip**。实测无换行（LF=0），
--   6 行前导空格 / 4 行行尾空格都落在物理行内部，内联进迁移不触发
--   `git diff --check`（该红线只查物理行尾空白）。14 行含 `$a{}`/`$r{}`
--   标记原样存储不解析。
-- - source_book_id：源 BookId → `book_info.id`（按 `book_info.book_no` 对映，
--   0175 种子 10 行全命中）；`source_book_legacy_id` 存源 BookId 便于追溯。
-- - source_chapter_legacy_id：源 `BookChapter.Id` 只读历史。0182 冻结映射
--   （`scripts/import-ctwh/book-chapter-ids.json`）据此把源
--   `BookChapterBody.BookChapterId` 关联到本表新 id，供 0186 正文种子使用；
--   0182 建了索引便于核对。
-- - source_book_name：源 BookName 原样，153/445 为 NULL（缺失时 UI 用
--   book_info 书名兜底显示）。
-- - is_enable：源 343=1 / 102=0，**全量导入含禁用**（禁用书卷章仍要能后台看见）。
-- - signature_id / signature：列位保留原值（App 签名链路），admin 不编辑。
-- - created_at / updated_at：源 CreateDate（全非空、0 格式不符）。
--
-- 幂等：INSERT OR IGNORE（id 主键），重复执行/重放安全；已存在行不覆盖。
--
-- 分批发语句：D1 对**单条 SQL 语句**的字面量上限是 100,000 字节
-- （docs/agents/d1-sync.md，实测 75KB 通过、135KB 报 SQLITE_TOOBIG）。
-- 445 行拼成一条会到 ~96.7KB，余量只剩 3.3%。这里每 60 行
-- 一条 INSERT，单条实测 13,843 字节（生成期阈值 32KB），
-- 给字段增补留足空间。同批 zhong_yao 0180 也是多条语句
-- （22 条语句含 19 条 INSERT，单条最大 8,645 字节）。

INSERT OR IGNORE INTO book_chapter
  (id, chapter_no, chapter_header, source_book_id, source_book_name,
   source_book_legacy_id, source_chapter_legacy_id, chapter_section, is_enable,
   signature_id, signature, created_at, updated_at)
